-- 건강기능식품 축약본(1,000개판): 시나리오·페르소나 성분 + 범주별 브랜드·최근 등록 제품 (1000개)
-- 원본: 건강기능식품_전체_1-46101.csv(제품) · database/health_food_ingredient.csv.gz(원재료)
-- 구조는 database/health_food.sql과 같고 테이블 이름 앞에 new_. staging 단계 없이 바로 넣는다.
-- Supabase SQL Editor에 전체를 붙여넣고 Run. 다시 실행하면 new_health_food·new_health_food_ingredient를 지우고 새로 만든다.
-- 03_new_nutrient_interaction.sql의 뷰가 new_health_food를 참조하므로 cascade로 함께 지운다. 이 파일을 다시 실행했으면 03도 다시 실행한다.
-- 원재료 26399행

begin;

drop table if exists public.new_health_food_ingredient;
drop table if exists public.new_health_food cascade;

create table public.new_health_food (
  report_no          text primary key,          -- 신고번호
  list_no            integer,                   -- 번호
  name               text not null,             -- 제품명
  list_name          text,                      -- 목록_제품명
  company            text,                      -- 제조사명
  list_functionality text,                      -- 목록_기능성
  registered_at      date,                      -- 등록일자
  shelf_life         text,                      -- 유통기한
  appearance         text,                      -- 성상
  intake_method      text,                      -- 섭취량/섭취방법
  packaging          text,                      -- 포장재질(방법)
  functionality      text,                      -- 기능성 내용
  storage            text,                      -- 보존 및 유통기준
  precautions        text,                      -- 섭취 시 주의사항
  ingredient_count   integer,
  pick_category      text,                      -- 축약본 범주 (원본에 없는 열)
  pick_reason        text                       -- 축약본에 넣은 이유 (원본에 없는 열)
);

-- 원재료 테이블 (제품 1 : N 원재료)
create table public.new_health_food_ingredient (
  id              bigint generated always as identity primary key,
  report_no       text not null references public.new_health_food(report_no) on delete cascade,
  ingredient_type text not null check (ingredient_type in ('functional','other','capsule')),
                  -- functional=기능성 원재료명, other=기타 원재료명, capsule=캡슐 원재료명
  seq             integer not null,             -- 원본 목록 내 순서
  ingredient_name text not null
);

